{"code": "import requests
import json

orcid_ids = [
    ("Manuela Nagel", "0000-0003-0396-0333"),
    ("Tatjana Gavrilenko", "0000-0002-2605-6569"),
    ("John Bamberg", "0000-0001-6102-7846"),
    ("David Ellis", "0000-0002-0209-2784"),
    ("Peter Giovannini", "0000-0002-1053-2030"),
]

results = {}

for name, orcid_id in orcid_ids:
    url = f"https://pub.orcid.org/v2.0/{orcid_id}/works"
    headers = {"Accept": "application/json"}
    response = requests.get(url, headers=headers)
    print(f"{name} ({orcid_id}): Status {response.status_code}")

    if response.status_code == 200:
        data = response.json()
        pre_2020_count = 0
        total_works = 0

        if 'group' in data:
            for group in data['group']:
                if 'work-summary' in group:
                    for summary in group['work-summary']:
                        total_works += 1
                        # Check for publication date
                        pub_date = summary.get('publication-date', {})
                        if pub_date:
                            year = pub_date.get('year', {})
                            if year and 'value' in year:
                                year_value = int(year['value'])
                                if year_value < 2020:
                                    pre_2020_count += 1

        results[name] = {
            'orcid': orcid_id,
            'total_works': total_works,
            'pre_2020': pre_2020_count
        }
        print(f"  Total works: {total_works}, Pre-2020: {pre_2020_count}")
    else:
        print(f"  Error: {response.text[:200]}")
        results[name] = {'orcid': orcid_id, 'total_works': 0, 'pre_2020': 0}

# Calculate average
pre_2020_counts = [r['pre_2020'] for r in results.values()]
average = sum(pre_2020_counts) / len(pre_2020_counts)

print("\n--- Summary ---")
for name, data in results.items():
    print(f"{name}: {data['pre_2020']} pre-2020 works out of {data['total_works']} total")

print(f"\nAverage pre-2020 works: {average}")"}
